/** Two columns adopt one four-foot native group, then publish edits to both client columns. */
@net.minecraftforge.fml.relauncher.SideOnly(net.minecraftforge.fml.relauncher.Side.CLIENT)
public final class ArmJoinedLandingLiveChecks {
    private static final BlockPos ROOT=new BlockPos(1280,155,160);private static final boolean WHEELS="true".equals(System.getenv("VANDOR_ARMS_210_JOINED_WHEELS_ONLY"));private static final int START=Integer.parseInt(System.getenv().getOrDefault("VANDOR_ARMS_210_JOINED_START","0")),END=Integer.parseInt(System.getenv().getOrDefault("VANDOR_ARMS_210_JOINED_END",WHEELS?"12":"60"));private static int fixture=START,stage,ticks,started;private static boolean clicked,bound;private static java.util.List<BlockPos> formerFeet;
    private static int profile(){return fixture%30;}private static boolean rotates(){return fixture<(WHEELS?6:30);}private static boolean large(){return WHEELS||profile()>=18;}private static EnumFacing mount(){return EnumFacing.values()[fixture%6];}private static int sign(){return mount()==EnumFacing.WEST?-1:1;}
    private static GearBlock foot(){return WHEELS?GearRegistry.LARGE_LANDING_WHEEL:large()?profile()<24?GearRegistry.LANDING_PLATE:GearRegistry.LANDING_SKI:profile()/6==0?GearRegistry.LANDING_PLATE:profile()/6==1?GearRegistry.LANDING_SKI:GearRegistry.LANDING_WHEEL;}
    private static double cameraX(){return ROOT.getX()+4+(fixture&1)*.25;}
    private static BlockPos at(int x,int y){return ROOT.add(ArmOrientation.vector(mount(),new BlockPos(x*sign(),y,0)));}
    private static void need(boolean ok,String reason){if(!ok)throw new IllegalStateException("arm-joined-landing fixture="+fixture+" stage="+stage+" tick="+ticks+" mount="+mount()+": "+reason);}
    private static void put(WorldServer world,EntityPlayerMP actor,BlockPos pos,EnumFacing face){ItemBlock item=(ItemBlock)Item.getItemFromBlock(foot());need(item.placeBlockAt(new ItemStack(item),actor,world,pos,face,.5F,.5F,.5F,foot().getDefaultState()),"ordinary native foot placement");((GearTileEntity)world.getTileEntity(pos)).setMountDirection(face);}
    private static boolean clients(Minecraft mc,int feet){TileEntity raw=mc.world.getTileEntity(ROOT);if(!(raw instanceof GearTileEntity))return false;GearTileEntity root=(GearTileEntity)raw;if(root.mountDirection()!=mount()||root.progress()!=1||root.columns().size()!=2||root.isLandingAssembly()!=(feet>0)||feet>0&&root.assembly().feet().size()!=feet)return false;int renderers=0;for(BlockPos pos:root.members()){TileEntity member=mc.world.getTileEntity(pos);if(!(member instanceof GearTileEntity)||((GearTileEntity)member).loadedController()!=root||((GearTileEntity)member).mountDirection()!=mount())return false;if(com.vandorlabs.gear.client.GearRenderer.visible((GearTileEntity)member))renderers++;}if(formerFeet!=null)for(BlockPos pos:formerFeet)if(!root.members().contains(pos)&&!mc.world.isAirBlock(pos))return false;return renderers==1;}
    public static boolean tick(Minecraft mc)throws Exception{
        if(fixture==END){System.out.println("[vandorlabs][reprolab] arm-joined-landing PASS cases="+(END-START)+" six mounts both modes regular/Large native-foot two-column ownership async journals active/native endpoint reload client owner one-renderer partial/complete mining");System.out.println("[vandorlabs][reprolab] utility26-focused PASS arms-210-joined-landing");return true;}ticks++;mc.displayGuiScreen(null);
        if(stage==1||stage==3){need(ticks-started<300,"client creative/slot/held/position synchronization mode="+mc.playerController.getCurrentGameType()+" slot="+mc.player.inventory.currentItem+" held="+mc.player.getHeldItemMainhand()+" server="+ArmInteractionSync.status());if(!clicked&&mc.playerController.getCurrentGameType()==GameType.CREATIVE&&mc.player.inventory.currentItem==0&&mc.player.getHeldItemMainhand().isEmpty()&&mc.player.getDistanceSq(cameraX(),ROOT.getY()+3,ROOT.getZ()-4)<.0001&&ArmInteractionSync.acknowledged(mc)){mc.player.connection.sendPacket(new CPacketPlayerTryUseItemOnBlock(ROOT,mount(),EnumHand.MAIN_HAND,.5F,.5F,.5F));clicked=true;}if(!clicked)return false;}
        if(stage==5||stage==7||stage==9){need(ticks-started<300,"client native members retain mounting controller and one renderer");if(!clients(mc,stage==5?(WHEELS?12:4):stage==7?(WHEELS?8:3):0))return false;stage++;started=ticks;}
        return mc.getIntegratedServer().callFromMainThread(()->{
            WorldServer world=mc.getIntegratedServer().getWorld(0);EntityPlayerMP actor=mc.getIntegratedServer().getPlayerList().getPlayers().get(0);
            if(stage==0){bound=false;ArmEndpointLandingCaps.enable();for(BlockPos pos:BlockPos.getAllInBox(ROOT.add(-9,-9,-9),ROOT.add(9,9,9))){world.removeTileEntity(pos);world.setBlockToAir(pos);}actor.setGameType(GameType.CREATIVE);actor.capabilities.isFlying=true;actor.sendPlayerAbilities();actor.inventory.currentItem=0;GearBlock arm=large()?GearRegistry.LARGE_GEAR_SWING_ARM:GearRegistry.GEAR_SWING_ARM;
                for(int x:new int[]{0,2}){world.setBlockState(at(x,1),Blocks.STONE.getDefaultState(),2);actor.setHeldItem(EnumHand.MAIN_HAND,new ItemStack(arm,2));for(int n=1;n>=0;n--)need(actor.getHeldItemMainhand().onItemUse(actor,world,at(x,n),EnumHand.MAIN_HAND,mount(),.5F,.5F,.5F)==EnumActionResult.SUCCESS,"ordinary supported joined column placement");GearTileEntity column=(GearTileEntity)world.getTileEntity(at(x,0));column.operator(actor);need(column.rebuild(),"column forms");NBTTagCompound settings=column.settings();settings.setBoolean("JoinArms",true);settings.setInteger("JoinRange",3);settings.setBoolean("RotatePayload",rotates());column.configure(settings);}
                GearTileEntity root=(GearTileEntity)world.getTileEntity(ROOT);need(root.rebuild()&&root.columns().size()==2,"bare joined columns form");if(!rotates()){placeGroup(world,actor,root,null);need(root.rebuild()&&root.assembly().feet().size()==(WHEELS?12:4),"native deployed level landing group forms");}
                ArmActiveLanding.testBound=active->{if(active.getPos().equals(ROOT)){need(active.progress()==0&&active.isLandingAssembly()&&active.columns().size()==2&&active.assembly().feet().size()==(WHEELS?12:4),"joined group binds while active");for(com.vandorlabs.gear.core.GearTopology.Cell cell:active.assembly().feet())need(world.getTileEntity(active.localCell(cell)) instanceof GearTileEntity&&((GearTileEntity)world.getTileEntity(active.localCell(cell))).loadedController()==active,"every native foot belongs to active joined controller");bound=true;}};actor.setHeldItem(EnumHand.MAIN_HAND,ItemStack.EMPTY);actor.inventoryContainer.detectAndSendChanges();actor.connection.setPlayerLocation(cameraX(),ROOT.getY()+3,ROOT.getZ()-4,0,0);stage=1;started=ticks;clicked=false;return false;}
            GearTileEntity root=(GearTileEntity)world.getTileEntity(ROOT);if(stage==1||stage==3){stage++;started=ticks;return false;}need(ticks-started<450,"joined stroke/journal completes phase="+root.progress()+" target="+root.target()+" error="+root.error()+" "+ArmTransactions.diagnostic(world,ROOT));if(ArmTransactions.locked(world,ROOT)||ArmTransactions.blocked(root))return false;
            if(stage==2){if(root.progress()!=0){if(root.target()&&ticks-started>20)need(false,"activation refused phase="+root.progress()+" landing="+root.isLandingAssembly()+" columns="+root.columns()+" error="+root.error()+" state="+root.writeToNBT(new NBTTagCompound()));return false;}if(rotates()){ArmPayload.Endpoint endpoint=ArmPayload.endpoint(root,0);need(endpoint!=null,"joined active rigid endpoint is grid aligned");placeGroup(world,actor,root,endpoint);}else need(root.isLandingAssembly()&&root.assembly().feet().size()==(WHEELS?12:4),"level native group survives active stroke");stage=3;started=ticks;clicked=false;return false;}
            if(stage==4){if(root.progress()!=1||!root.isLandingAssembly())return false;need(!rotates()||bound,"new group traverses real active binding");formerFeet=new java.util.ArrayList<>();for(com.vandorlabs.gear.core.GearTopology.Cell cell:root.assembly().feet()){BlockPos pos=root.localCell(cell);formerFeet.add(pos);GearTileEntity member=(GearTileEntity)world.getTileEntity(pos);need(member.loadedController()==root&&member.writeToNBT(new NBTTagCompound()).getCompoundTag("ForgeCaps").getCompoundTag(ArmEndpointLandingCaps.KEY.toString()).getInteger("Representation")==22,"one native landing owner retains physical capabilities");}NBTTagCompound saved=root.writeToNBT(new NBTTagCompound());root.readFromNBT(saved);root.operator(actor);root.onLoad();root.sync();stage=5;started=ticks;return false;}
            if(stage==6){need(actor.interactionManager.tryHarvestBlock(at(WHEELS?4:3,-2))&&root.rebuild()&&root.assembly().feet().size()==(WHEELS?8:3),"partial foot mining preserves both joined columns");stage=7;started=ticks;return false;}
            if(stage==8){for(int x:WHEELS?new int[]{0,2}:new int[]{0,1,2})need(actor.interactionManager.tryHarvestBlock(at(x,-2)),"complete foot mining succeeds");need(root.rebuild()&&!root.isLandingAssembly()&&root.columns().size()==2,"bare joined columns reform with no retained native foot");for(BlockPos pos:formerFeet)need(world.isAirBlock(pos),"all native helpers retired after complete group mining");stage=9;started=ticks;return false;}
            need(stage==10&&root.payload()==null&&!root.hasRetainedPayload(),"complete mining leaves no duplicate owner");System.out.println("[vandorlabs][reprolab] arm-joined-landing case PASS fixture="+fixture+" mount="+mount()+" Large="+large()+" rotates="+rotates()+" wheels="+WHEELS);ArmActiveLanding.testBound=null;fixture++;stage=0;started=ticks;clicked=false;return false;
        }).get();
    }
    private static void placeGroup(WorldServer world,EntityPlayerMP actor,GearTileEntity root,ArmPayload.Endpoint endpoint){if(!WHEELS){for(int x=0;x<4;x++)put(world,actor,endpoint==null?at(x,-2):endpoint.placed(at(x,-2)),endpoint==null?mount():endpoint.mappedFacing(mount()));return;}for(int x:new int[]{0,2,4}){BlockPos home=at(x,-2);net.minecraft.block.state.IBlockState state=foot().getDefaultState().withProperty(GearBlock.FACING,world.getBlockState(ROOT).getValue(GearBlock.FACING));EnumFacing frame=mount();if(endpoint!=null){NBTTagCompound data=new NBTTagCompound();data.setString("id",TileEntity.getKey(GearTileEntity.class).toString());data.setString("ArmMountDirection",mount().name());ArmFootComponentFrame.write(data,mount());state=endpoint.placedState(new com.vandorlabs.vehicle.VehicleStructure.Cell(home,state,data));need(state!=null,"complete joined wheel frame maps to active plane");frame=endpoint.mappedFacing(mount());}ItemBlock item=(ItemBlock)Item.getItemFromBlock(foot());try(ArmFootComponentFrame.Placement placement=ArmFootComponentFrame.placing(frame,state.getValue(GearBlock.FACING))){need(item.placeBlockAt(new ItemStack(item),actor,world,endpoint==null?home:endpoint.placed(home),frame,.5F,.5F,.5F,state),"ordinary complete native wheel placement in joined plane");}}}
    private ArmJoinedLandingLiveChecks(){}
}
